CREATE TABLE stations(id TEXT PRIMARY KEY,name TEXT NOT NULL);CREATE TABLE products(id TEXT PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,archived INTEGER NOT NULL DEFAULT 0);CREATE TABLE station_products(station_id TEXT NOT NULL,product_id TEXT NOT NULL,PRIMARY KEY(station_id,product_id));CREATE TABLE inspections(work_date TEXT NOT NULL,station_id TEXT NOT NULL,product_id TEXT NOT NULL,product_name_snapshot TEXT NOT NULL,status TEXT NOT NULL,completed INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(work_date,station_id,product_id));CREATE TABLE shortages(id TEXT PRIMARY KEY,station_id TEXT NOT NULL,product_id TEXT NOT NULL,product_name TEXT NOT NULL,opened TEXT NOT NULL,resolved TEXT);INSERT INTO stations VALUES('large1','Large MK 1'),('large2','Large MK 2'),('small1','Small MK 1'),('small2','Small MK 2');